from common import *
c='24'
S2='(213,599B 본, 195,897B 블라인드본 지문 일치)'
def ty(n,ans,both=True): return t2(c,f'{n}번 복기',ans,'typed')
nt0='복기본(번호 51~77은 지문 없이 번호만 남음, 문항 누락 가능). 본 문항은 213,599B 본에 있음'
def bl(n): return ' · 195,897B 블라인드본에도 있음(dup)' if n in BLIND else ' · 195,897B 블라인드본에 없음(213,599B 본에만 있음)'
BLIND={1,2,4,5,7,10,12,13,14,18,19,22,23,24,25,30,34,36,38,39,42,44,47,49,50}
def a24(n,*a,**k):
    k['nt']=(k.get('nt','')+bl(n)).strip()
    k['sources']=[SRC['24']+' (213,599B)']+(['… (195,897B 블라인드본)','24학번 docx 2벌(26,350B / 24,810B)'] if n in BLIND else ['… docx(26,350B)'])
    return add(c,n,*a,**k)
